{"version":3,"file":"http.js","sources":["api/http.js"],"sourcesContent":["//let baseUrl = 'https://joinup.org.cn/api-dev'\r\nlet baseUrl = 'https://joinup.org.cn/api'\r\nimport { useUserStore } from '../stores/user.js'\r\n// 给参数 data 设置了一个默认值，即一个空对象 {}\r\nexport default function http(url1, data = {}, method) {\r\n  \r\n  return new Promise((resolve, reject) => {\r\n    uni.request({\r\n      url:baseUrl + url1,\r\n      data,\r\n      method:method,\r\n      header:{\r\n        'Content-Type': 'application/json',\r\n        'Authorization':   uni.getStorageSync('token') || ''\r\n      },\r\n      \r\n      success: res => {\r\n        if (res.statusCode == 200||res.statusCode == 201) {\r\n          if(data=='r'||url1==\"/user/verify\"||url1==\"/course/task/add\"){\r\n\t\t\t    if (res.data.code == 1) {\r\n              resolve(res.data)\r\n            } else if (res.data.code == 0) {\r\n              uni.showToast({\r\n                title:res.data.msg,\r\n                icon:'none'\r\n              })\r\n              reject(res.data.msg)\r\n            }\r\n//             resolve(res.data)\r\n          }else{\r\n            if (res.data.code == 1) {\r\n              resolve(res.data.data)\r\n            } else if (res.data.code == 0) {\r\n              uni.showToast({\r\n                title:res.data.msg,\r\n                icon:'none'\r\n              })\r\n              reject(res.data.msg)\r\n            }\r\n          }\r\n        }\r\n      },\r\n      \r\n      fail: (err) => {\r\n        console.log(\"请求失败:\", err);\r\n        uni.showToast({\r\n          title: '服务器请求错误',\r\n          icon: 'none'\r\n        });\r\n        reject(err);\r\n      }\r\n    })\r\n  })\r\n}\r\n\r\n"],"names":["uni"],"mappings":";;;AACA,IAAI,UAAU;AAGC,SAAS,KAAK,MAAM,OAAO,CAAA,GAAI,QAAQ;AAEpD,SAAO,IAAI,QAAQ,CAAC,SAAS,WAAW;AACtCA,kBAAAA,MAAI,QAAQ;AAAA,MACV,KAAI,UAAU;AAAA,MACd;AAAA,MACA;AAAA,MACA,QAAO;AAAA,QACL,gBAAgB;AAAA,QAChB,iBAAmBA,cAAG,MAAC,eAAe,OAAO,KAAK;AAAA,MACnD;AAAA,