{"version":3,"file":"http.js","sources":["api/http.js"],"sourcesContent":["let baseUrl = 'https://joinup.org.cn/api'\n// let baseUrl = 'https://joinup.org.cn/api'\nimport { useUserStore } from '../stores/user.js'\n// 给参数 data 设置了一个默认值，即一个空对象 {}\nexport default function http(url1, data = {}, method) {\n  \n  return new Promise((resolve, reject) => {\n    uni.request({\n      url:baseUrl + url1,\n      data,\n      method:method,\n      header:{\n        'Content-Type': 'application/json',\n        'Authorization':   uni.getStorageSync('token') || ''\n      },\n      \n      success: res => {\n        if (res.statusCode == 200||res.statusCode == 201) {\n          if(data=='r'||url1==\"/user/verify\"||url1==\"/course/task/add\"){\n\t\t\t    if (res.data.code == 1) {\n              resolve(res.data)\n            } else if (res.data.code == 0) {\n              uni.showToast({\n                title:res.data.msg,\n                icon:'none'\n              })\n              reject(res.data.msg)\n            }\n//             resolve(res.data)\n          }else{\n            if (res.data.code == 1) {\n              resolve(res.data.data)\n            } else if (res.data.code == 0) {\n              uni.showToast({\n                title:res.data.msg,\n                icon:'none'\n              })\n              reject(res.data.msg)\n            }\n          }\n        }\n      },\n      \n      fail: (err) => {\n        console.log(\"请求失败:\", err);\n        uni.showToast({\n          title: '服务器请求错误',\n          icon: 'none'\n        });\n        reject(err);\n      }\n    })\n  })\n}\n\n"],"names":["uni"],"mappings":";;;AAAA,IAAI,UAAU;AAIC,SAAS,KAAK,MAAM,OAAO,CAAA,GAAI,QAAQ;AAEpD,SAAO,IAAI,QAAQ,CAAC,SAAS,WAAW;AACtCA,kBAAAA,MAAI,QAAQ;AAAA,MACV,KAAI,UAAU;AAAA,MACd;AAAA,MACA;AAAA,MACA,QAAO;AAAA,QACL,gBAAgB;AAAA,QAChB,iBAAmBA,cAAG,MAAC,eAAe,OAAO,KAAK;AAAA,MACnD;AAAA,MAED,SAAS,SAAO;AACd,YAAI,IAAI,cAAc,OAAK,IAAI,cAAc,KAAK;AAChD,cAAG,QAAM,OAAK,QAAM,kBAAgB,QAAM,oBAAmB;AAChE,gBAAI,I